const tg = $input.first().json;
const raw = (((tg.message && tg.message.text) || tg.ticker || '')).trim();
if(!raw){ throw new Error('Пустой ввод — укажите тикер или название компании'); }
const chat_id = (tg.message && tg.message.chat && tg.message.chat.id) || tg.chat_id || null;
const SVC='YOUR_PYTHON_SERVICE_URL';
// v4.2.1: macro/price failures used to be swallowed by a bare `catch(e){}` -- risk_free and the
// price series would come back null with NO stated reason, and a null risk_free silently voids
// beta and every downstream discount. Collect reasons here and RETURN them: a missing number
// must always arrive with the reason it is missing.
const diag = {};
// SEC fair-access requires an identifying contact. This is NOT a secret -- the SEC wants to
// know who is calling. It stays inline because n8n 2.x Code nodes run in a task-runner
// sandbox with no access to env vars at all.
const UA='YOUR_NAME your@email.com';
// v4.2: the Tiingo and FRED keys are GONE from n8n. Those calls moved to the microservice
// (/macro_prices), which reads its own Railway environment. n8n orchestrates; it holds no
// data-source credentials. Exact variable names live in SETUP_railway.md, Part 1.
const http=this.helpers.httpRequest;
const list=await http({method:'GET',url:'https://www.sec.gov/files/company_tickers.json',headers:{'User-Agent':UA},json:true,timeout:20000});

const entries = Object.keys(list).map(k=>list[k]).filter(Boolean);
const ALIAS = {'GOOGLE':'GOOGL','ALPHABET':'GOOGL','FACEBOOK':'META','INSTAGRAM':'META','WHATSAPP':'META','GOOGL':'GOOGL'};
const norm = s => String(s||'').toLowerCase()
  .replace(/[.,&/\\()'"+-]/g,' ')
  .replace(/\b(inc|incorporated|corp|corporation|company|co|ltd|limited|plc|holdings|holding|group|the|sa|nv|ag|class|common|stock|ordinary|shares|adr|technologies|technology|international)\b/g,' ')
  .replace(/\s+/g,' ').trim();
const tickerCand = raw.toUpperCase().replace('$','').replace(/\s+/g,'');
let chosen=null, resolvedFrom=null;
// 1) alias map (brand name != legal name, e.g. Google->Alphabet)
if(ALIAS[tickerCand]){ chosen=entries.find(e=>e.ticker===ALIAS[tickerCand])||null; if(chosen) resolvedFrom='alias ("'+raw+'" → '+chosen.ticker+')'; }
// 2) exact ticker
if(!chosen){ chosen=entries.find(e=>e.ticker===tickerCand)||null; if(chosen) resolvedFrom='ticker'; }
// 3) company name match (against SEC title)
if(!chosen){
  const q=norm(raw);
  if(q){
    let cands=entries.filter(e=>norm(e.title)===q);
    if(!cands.length) cands=entries.filter(e=>norm(e.title).startsWith(q));
    if(!cands.length) cands=entries.filter(e=>(' '+norm(e.title)+' ').indexOf(' '+q+' ')>=0);
    if(!cands.length) cands=entries.filter(e=>norm(e.title).indexOf(q)>=0);
    if(cands.length){
      cands.sort((a,b)=> norm(a.title).length-norm(b.title).length || a.ticker.localeCompare(b.ticker));
      chosen=cands[0];
      const alt=cands.slice(0,4).map(e=>e.ticker+' ('+e.title+')').join('; ');
      resolvedFrom='name ("'+raw+'" → '+chosen.ticker+'; '+cands.length+' совпад.; топ: '+alt+')';
    }
  }
}
if(!chosen){ throw new Error('Не найдено ни тикера, ни компании по запросу: "'+raw+'". Уточните тикер или официальное название (реестр — только эмитенты SEC).'); }
const ticker = chosen.ticker;
const company_title = chosen.title;

const cik10=String(chosen.cik_str).padStart(10,'0');
let sic=null; try{ const sub=await http({method:'GET',url:'https://data.sec.gov/submissions/CIK'+cik10+'.json',headers:{'User-Agent':UA},json:true,timeout:20000}); sic=sub.sic?Number(sub.sic):null; }catch(e){}
const ANNUAL={'10-K':1,'20-F':1,'40-F':1}; let usedCurrency=null;
const _ccCache={};
const cc=async(ns,tag)=>{ const k=ns+':'+tag; if(k in _ccCache) return _ccCache[k]; try{ const r=await http({method:'GET',url:'https://data.sec.gov/api/xbrl/companyconcept/CIK'+cik10+'/'+ns+'/'+tag+'.json',headers:{'User-Agent':UA},json:true,timeout:20000}); _ccCache[k]=r; return r; }catch(e){ _ccCache[k]=null; return null; } };
const pickU=(r)=>{ const uk=Object.keys(r.units); const u=(uk.indexOf('USD')>=0)?'USD':uk[0]; if(!usedCurrency)usedCurrency=u; return u; };
const A=async(cands)=>{ let m=[]; for(const c of cands){ const r=await cc(c.ns,c.tag); if(r&&r.units){ const u=pickU(r); m=m.concat(r.units[u].filter(x=>x.val!=null&&ANNUAL[x.form])); } } if(!m.length)return null; const b={}; for(const x of m){ if(!b[x.end]||(x.filed||'')>(b[x.end].filed||''))b[x.end]=x; } return Object.keys(b).map(k=>b[k]).sort((p,q)=>new Date(p.end)-new Date(q.end)).map(x=>({end:x.end,val:x.val})); };
const I=async(cands)=>{ const s=await A(cands); return s&&s.length?s[s.length-1].val:null; };
const Q=async(cands)=>{ let m=[]; for(const c of cands){ const r=await cc(c.ns,c.tag); if(r&&r.units){ const u=pickU(r); m=m.concat(r.units[u].filter(x=>x.val!=null&&x.form==='10-Q'&&x.start&&x.end)); } } if(!m.length)return null; const disc=m.filter(x=>{const d=(new Date(x.end)-new Date(x.start))/86400000; return d>=80&&d<=100;}); const b={}; for(const x of disc){ if(!b[x.end]||(x.filed||'')>(b[x.end].filed||''))b[x.end]=x; } const s=Object.keys(b).map(k=>b[k]).sort((p,q)=>new Date(p.end)-new Date(q.end)).map(x=>({end:x.end,val:x.val})); return s.length?s.slice(-5):null; };
const QYTD=async(cands)=>{ let m=[]; for(const c of cands){ const r=await cc(c.ns,c.tag); if(r&&r.units){ const u=pickU(r); m=m.concat(r.units[u].filter(x=>x.val!=null&&x.form==='10-Q'&&x.start&&x.end)); } } if(!m.length)return null; let best=null; for(const x of m){ if(!best||x.end>best.end||(x.end===best.end&&(x.filed||'')>(best.filed||''))) best=x; } return best?{start:best.start,end:best.end,val:best.val}:null; };
// income / cashflow series
const revenue=await A([{ns:'us-gaap',tag:'RevenueFromContractWithCustomerExcludingAssessedTax'},{ns:'us-gaap',tag:'Revenues'},{ns:'ifrs-full',tag:'Revenue'}]);
const gross_profit=await A([{ns:'us-gaap',tag:'GrossProfit'}]);
const cost_of_revenue=await A([{ns:'us-gaap',tag:'CostOfRevenue'},{ns:'us-gaap',tag:'CostOfGoodsAndServicesSold'},{ns:'us-gaap',tag:'CostOfServices'}]);
const operating_income=await A([{ns:'us-gaap',tag:'OperatingIncomeLoss'},{ns:'ifrs-full',tag:'ProfitLossFromOperatingActivities'}]);
const net_income=await A([{ns:'us-gaap',tag:'NetIncomeLoss'},{ns:'ifrs-full',tag:'ProfitLoss'}]);
const ocf=await A([{ns:'us-gaap',tag:'NetCashProvidedByUsedInOperatingActivities'},{ns:'ifrs-full',tag:'CashFlowsFromUsedInOperatingActivities'}]);
const capex=await A([{ns:'us-gaap',tag:'PaymentsToAcquirePropertyPlantAndEquipment'},{ns:'us-gaap',tag:'PaymentsToAcquireProductiveAssets'},{ns:'us-gaap',tag:'PaymentsForCapitalImprovements'},{ns:'ifrs-full',tag:'PurchaseOfPropertyPlantAndEquipmentClassifiedAsInvestingActivities'}]);
const sbc=await A([{ns:'us-gaap',tag:'ShareBasedCompensation'},{ns:'us-gaap',tag:'AllocatedShareBasedCompensationExpense'},{ns:'us-gaap',tag:'ShareBasedPaymentArrangementExpense'},{ns:'ifrs-full',tag:'ShareBasedPaymentsExpense'}]);
const dna=await A([{ns:'us-gaap',tag:'DepreciationDepletionAndAmortization'},{ns:'us-gaap',tag:'DepreciationAmortizationAndAccretionNet'},{ns:'us-gaap',tag:'DepreciationAndAmortization'},{ns:'us-gaap',tag:'Depreciation'}]);
// v2.3 wave-1 step2: buyback executed (cash outflow for share repurchase) from SEC XBRL, primary source
const buyback=await A([{ns:'us-gaap',tag:'PaymentsForRepurchaseOfCommonStock'},{ns:'us-gaap',tag:'PaymentsForRepurchaseOfEquity'},{ns:'us-gaap',tag:'TreasuryStockValueAcquiredCostMethod'}]);
// dividends paid (cash outflow) — closes dividend-history from primary source
const dividends_paid=await A([{ns:'us-gaap',tag:'PaymentsOfDividendsCommonStock'},{ns:'us-gaap',tag:'PaymentsOfDividends'}]);
const dep_only=await I([{ns:'us-gaap',tag:'Depreciation'},{ns:'us-gaap',tag:'DepreciationNonproduction'}]);
const amort_intang=await I([{ns:'us-gaap',tag:'AmortizationOfIntangibleAssets'}]);
let dna_latest=(dna&&dna.length)?dna[dna.length-1].val:null;
if(dna_latest==null && (dep_only!=null||amort_intang!=null)) dna_latest=(dep_only||0)+(amort_intang||0);
const shares_diluted=await A([{ns:'us-gaap',tag:'WeightedAverageNumberOfDilutedSharesOutstanding'},{ns:'us-gaap',tag:'WeightedAverageNumberOfSharesOutstandingBasic'}]);
// bank / insurer
const nii=await A([{ns:'us-gaap',tag:'InterestIncomeExpenseNet'},{ns:'us-gaap',tag:'InterestIncomeExpenseAfterProvisionForLoanLoss'}]);
const interest_income=await A([{ns:'us-gaap',tag:'InterestAndDividendIncomeOperating'},{ns:'us-gaap',tag:'InterestAndFeeIncomeLoansAndLeases'}]);
const interest_expense=await A([{ns:'us-gaap',tag:'InterestExpense'}]);
const provision=await A([{ns:'us-gaap',tag:'ProvisionForLoanLossesExpensed'},{ns:'us-gaap',tag:'ProvisionForLoanLeaseAndOtherLosses'},{ns:'us-gaap',tag:'ProvisionForDoubtfulAccounts'}]);
const noninterest_expense=await A([{ns:'us-gaap',tag:'NoninterestExpense'},{ns:'us-gaap',tag:'OperatingExpenses'}]);
const noninterest_income=await A([{ns:'us-gaap',tag:'NoninterestIncome'},{ns:'us-gaap',tag:'FeesAndCommissionsNet'}]);
const premiums=await A([{ns:'us-gaap',tag:'PremiumsEarnedNet'},{ns:'us-gaap',tag:'HealthCareOrganizationRevenue'},{ns:'us-gaap',tag:'PremiumsEarnedNetPropertyCasualty'}]);
const benefits=await A([{ns:'us-gaap',tag:'PolicyholderBenefitsAndClaimsIncurredNet'},{ns:'us-gaap',tag:'PolicyholderBenefitsAndClaimsIncurredHealthCare'},{ns:'us-gaap',tag:'BenefitsLossesAndExpenses'}]);
// instant
const cash=await I([{ns:'us-gaap',tag:'CashAndCashEquivalentsAtCarryingValue'},{ns:'ifrs-full',tag:'CashAndCashEquivalents'}]);
const restricted_cash=await I([{ns:'us-gaap',tag:'RestrictedCashAndCashEquivalentsAtCarryingValue'},{ns:'us-gaap',tag:'RestrictedCash'},{ns:'ifrs-full',tag:'RestrictedCashAndCashEquivalents'}]);
const dLtnc=await I([{ns:'us-gaap',tag:'LongTermDebtNoncurrent'}]);
const dLtcur=await I([{ns:'us-gaap',tag:'LongTermDebtCurrent'}]);
const dLt=await I([{ns:'us-gaap',tag:'LongTermDebt'}]);
const dComb=await I([{ns:'us-gaap',tag:'DebtLongtermAndShorttermCombinedAmount'}]);
const dCapLease=await I([{ns:'us-gaap',tag:'LongTermDebtAndCapitalLeaseObligations'}]);
const dIfrs=await I([{ns:'ifrs-full',tag:'Borrowings'}]);
const dNcCur=(dLtnc!=null||dLtcur!=null)?((dLtnc||0)+(dLtcur||0)):null;
const debt_components={ noncurrent_plus_current:dNcCur, long_term_debt:dLt, ltd_plus_finance_leases:dCapLease, combined_short_long:dComb, ifrs_borrowings:dIfrs };
const _ie=(interest_expense&&interest_expense.length)?interest_expense[interest_expense.length-1].val:null;
const _prio=['noncurrent_plus_current','long_term_debt','ltd_plus_finance_leases','combined_short_long','ifrs_borrowings'];
let total_debt=null,total_debt_source=null,implied_interest_rate=null,total_debt_divergence=false,alt_total_debt=null,alt_total_debt_source=null;
{ const avail=_prio.map(k=>({src:k,val:debt_components[k]})).filter(x=>x.val!=null&&x.val>0);
  if(avail.length){ let pick=avail[0];
    if(_ie!=null&&_ie>0){ const r=_ie/pick.val; if(r>0.15){ const bigger=avail.filter(x=>x.val>pick.val&&(_ie/x.val)>=0.015&&(_ie/x.val)<=0.15).sort((a,b)=>a.val-b.val); if(bigger.length) pick=bigger[0]; } }
    const mx=avail.reduce((a,b)=>b.val>a.val?b:a,avail[0]);
    if(mx.val>pick.val*1.3){ total_debt_divergence=true; alt_total_debt=mx.val; alt_total_debt_source=mx.src; }
    total_debt=pick.val; total_debt_source=pick.src; if(_ie!=null&&_ie>0) implied_interest_rate=_ie/total_debt; } }
const rpo=await I([{ns:'us-gaap',tag:'RevenueRemainingPerformanceObligation'}]);
const total_assets=await I([{ns:'us-gaap',tag:'Assets'},{ns:'ifrs-full',tag:'Assets'}]);
const total_equity=await I([{ns:'us-gaap',tag:'StockholdersEquity'},{ns:'us-gaap',tag:'StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest'},{ns:'ifrs-full',tag:'Equity'}]);
const goodwill=await I([{ns:'us-gaap',tag:'Goodwill'},{ns:'ifrs-full',tag:'Goodwill'}]);
const intangibles=await I([{ns:'us-gaap',tag:'IntangibleAssetsNetExcludingGoodwill'},{ns:'us-gaap',tag:'FiniteLivedIntangibleAssetsNet'}]);
const deposits=await I([{ns:'us-gaap',tag:'Deposits'},{ns:'us-gaap',tag:'InterestBearingDepositLiabilities'},{ns:'ifrs-full',tag:'DepositsFromCustomers'}]);
const loans=await I([{ns:'us-gaap',tag:'LoansAndLeasesReceivableNetReportedAmount'},{ns:'us-gaap',tag:'FinancingReceivableExcludingAccruedInterestAfterAllowanceForCreditLoss'},{ns:'ifrs-full',tag:'LoansAndAdvancesToCustomers'}]);
const ppe_gross=await I([{ns:'us-gaap',tag:'PropertyPlantAndEquipmentGross'}]);
const ppe_net=await I([{ns:'us-gaap',tag:'PropertyPlantAndEquipmentNet'},{ns:'ifrs-full',tag:'PropertyPlantAndEquipment'}]);
const st_investments=await I([{ns:'us-gaap',tag:'ShortTermInvestments'},{ns:'us-gaap',tag:'MarketableSecuritiesCurrent'},{ns:'us-gaap',tag:'AvailableForSaleSecuritiesCurrent'}]);
let shares_current=await I([{ns:'dei',tag:'EntityCommonStockSharesOutstanding'}]); if(shares_current==null) shares_current=await I([{ns:'us-gaap',tag:'CommonStockSharesOutstanding'}]); if(shares_current==null){ shares_current=(shares_diluted&&shares_diluted.length)?shares_diluted[shares_diluted.length-1].val:null; }
// macro + prices

let risk_free=null, stock=[], spy=[], monthly_prices=[];
try {
  const mp = await http({method:'POST', url:SVC+'/macro_prices',
    body:{ticker, benchmark:'SPY', start:'2023-01-01'}, json:true, timeout:45000});
  risk_free = (mp && mp.risk_free!=null) ? mp.risk_free : null;
  stock = (mp && Array.isArray(mp.prices)) ? mp.prices : [];
  spy   = (mp && Array.isArray(mp.benchmark_prices)) ? mp.benchmark_prices : [];
  monthly_prices = (mp && Array.isArray(mp.monthly_prices)) ? mp.monthly_prices : [];
  if (mp && mp._errors && Object.keys(mp._errors).length) diag.macro_prices = mp._errors;
} catch(e){ diag.macro_prices = String(e).slice(0,150); }
function _rets(a){const r=[];for(let i=1;i<a.length;i++){if(a[i-1]>0)r.push(a[i]/a[i-1]-1);}return r;}
let beta_raw=1.0, vol_ratio=1.0, beta=1.0, beta_vol_adjusted=false;
try{ const rs=_rets(stock), rm=_rets(spy); const n=Math.min(rs.length,rm.length);
  if(n>60){ const S=rs.slice(rs.length-n), M=rm.slice(rm.length-n);
    const mean=x=>x.reduce((a,b)=>a+b,0)/x.length; const ms=mean(S), mm=mean(M);
    let cov=0,vm=0,vs=0; for(let i=0;i<n;i++){cov+=(S[i]-ms)*(M[i]-mm); vm+=(M[i]-mm)**2; vs+=(S[i]-ms)**2;}
    beta_raw=vm>0?cov/vm:1.0; beta_raw=Math.max(0.3,Math.min(3.0,beta_raw));
    const sd_s=Math.sqrt(vs/n), sd_m=Math.sqrt(vm/n); vol_ratio=sd_m>0?sd_s/sd_m:1.0;
    const vol_floor=0.60*vol_ratio; beta=Math.min(2.5,Math.max(beta_raw,vol_floor)); beta_vol_adjusted=beta>beta_raw+1e-9;
  } }catch(e){ beta_raw=1.0; beta=1.0; }
const _series=[revenue,net_income,ocf,operating_income,capex,sbc,dna,nii,premiums,benefits,gross_profit];
let _maxEnd=null; for(const _s of _series){ if(Array.isArray(_s)){ for(const _x of _s){ if(_x&&_x.end&&(_maxEnd==null||_x.end>_maxEnd)) _maxEnd=_x.end; } } }
const latest_fy = _maxEnd ? String(_maxEnd).slice(0,4) : null;
function _lastEndYr(s){ if(Array.isArray(s)&&s.length){ let mx=null; for(const _x of s){ if(_x&&_x.end&&(mx==null||_x.end>mx)) mx=_x.end; } return mx?String(mx).slice(0,4):null; } return null; }
const series_latest={ revenue:_lastEndYr(revenue), gross_profit:_lastEndYr(gross_profit), operating_income:_lastEndYr(operating_income), net_income:_lastEndYr(net_income), ocf:_lastEndYr(ocf), capex:_lastEndYr(capex), sbc:_lastEndYr(sbc), dna:_lastEndYr(dna) };
const gross_profit_stale = (series_latest.gross_profit==null) || (latest_fy && series_latest.gross_profit && series_latest.gross_profit < latest_fy);
const q_revenue=await Q([{ns:'us-gaap',tag:'RevenueFromContractWithCustomerExcludingAssessedTax'},{ns:'us-gaap',tag:'Revenues'}]);
const q_operating_income=await Q([{ns:'us-gaap',tag:'OperatingIncomeLoss'}]);
const q_net_income=await Q([{ns:'us-gaap',tag:'NetIncomeLoss'}]);
const ocf_ytd_latest=await QYTD([{ns:'us-gaap',tag:'NetCashProvidedByUsedInOperatingActivities'}]);
const quarterly_recent={ revenue:q_revenue, operating_income:q_operating_income, net_income:q_net_income, ocf_ytd_latest };

// ===== EDGAR authoritative overlay (v1.8) — first-source SEC financials + sanity gates + cross-check =====
let edgar=null, edgar_flags={}, edgar_divergence={}, edgar_sources={};
try {
  edgar = await http({ method:'POST', url:SVC+'/edgar_facts', body:{ ticker }, json:true, timeout:25000 });
} catch(e){ edgar = { _errors:{ fetch:String(e).slice(0,140) } }; }
const _last = s => (Array.isArray(s)&&s.length) ? ((s[s.length-1]&&typeof s[s.length-1]==='object')?s[s.length-1].val:s[s.length-1]) : (typeof s==='number'?s:null);
const _gather = { revenue, gross_profit, operating_income, net_income, ocf, capex, sbc, shares_diluted, cash, short_term_investments:st_investments, restricted_cash, total_debt };
const EDGAR_FIELDS = ['revenue','gross_profit','operating_income','net_income','ocf','capex','sbc','shares_diluted','cash','restricted_cash','short_term_investments','total_debt'];
let edgarOverride = {};
if (edgar && !(edgar._errors && (edgar._errors.cik||edgar._errors.companyfacts))) {
  for (const f of EDGAR_FIELDS){
    const ev = edgar[f];
    if (ev===undefined || ev===null) continue;
    const en=_last(ev), gn=_last(_gather[f]);
    if (en!=null && gn!=null && Math.abs(gn)>0 && Math.abs(en-gn)/Math.abs(gn) > 0.05){
      edgar_divergence[f] = { edgar:en, gather:gn, pct:Math.round(Math.abs(en-gn)/Math.abs(gn)*1000)/10 };
    }
    edgarOverride[f] = ev;   // EDGAR authoritative
  }
  if (edgarOverride.revenue!==undefined) edgarOverride.total_revenue = edgarOverride.revenue;
  if (edgarOverride.short_term_investments!==undefined) edgarOverride.st_investments = edgarOverride.short_term_investments;
  if (edgar.shares_current!==undefined && edgar.shares_current!==null) edgarOverride.shares_current = edgar.shares_current;
  edgar_flags = edgar._flags||{}; edgar_sources = edgar._field_sources||{};
  // reconcile annual summaries with EDGAR-authoritative series (v2.1)
  const _eff = ff => (edgarOverride[ff]!==undefined ? edgarOverride[ff] : _gather[ff]);
  const _lastYr = s => (Array.isArray(s)&&s.length) ? (function(){var mx=null;for(var xi=0;xi<s.length;xi++){var x=s[xi];if(x&&x.end&&(mx==null||x.end>mx))mx=x.end;}return mx?String(mx).slice(0,4):null;})() : null;
  edgarOverride.series_latest = { revenue:_lastYr(_eff('revenue')), gross_profit:_lastYr(_eff('gross_profit')), operating_income:_lastYr(_eff('operating_income')), net_income:_lastYr(_eff('net_income')), ocf:_lastYr(_eff('ocf')), capex:_lastYr(_eff('capex')), sbc:_lastYr(_eff('sbc')), dna:series_latest.dna };
  const _rY=edgarOverride.series_latest.revenue, _gY=edgarOverride.series_latest.gross_profit;
  edgarOverride.gross_profit_stale = (_gY==null) || (_rY!=null && Number(_gY) < Number(_rY));
} else {
  edgar_flags = { edgar_unavailable:(edgar&&edgar._errors)||'no response — kept Gather Data SEC-inline values' };
}

return [{ json: {
  ticker, company_title, resolved_from:resolvedFrom, chat_id, sic, currency:usedCurrency, latest_fy, series_latest, gross_profit_stale, quarterly_recent, total_revenue:revenue,
  revenue, gross_profit, cost_of_revenue, operating_income, net_income, ocf, capex, sbc, dna, shares_diluted, buyback, dividends_paid,
  nii, interest_income, interest_expense, provision, noninterest_expense, noninterest_income, premiums, benefits,
  cash, st_investments, short_term_investments:st_investments, total_debt, total_debt_source, restricted_cash, debt_components, implied_interest_rate, total_debt_divergence, alt_total_debt, alt_total_debt_source, rpo, total_assets, total_equity, stockholders_equity:total_equity, goodwill, intangibles, deposits, loans, ppe_gross, ppe_net, dna_latest, shares_current,
  macro_data:{ risk_free, erp:0.046, beta, beta_raw, vol_ratio, beta_vol_adjusted },
  price_data:{ current_price:(stock.length?stock[stock.length-1]:null), stock, spy },
  ...edgarOverride,
  _edgar:{ flags:edgar_flags, divergence:edgar_divergence, sources:edgar_sources, cik:(edgar&&edgar._cik)||null },
  monthly_prices,
  _macro_diag: diag
} }];

const SVC='YOUR_PYTHON_SERVICE_URL';  // v4.2: the only non-secret value n8n still needs

const s = $input.first().json;
const http = this.helpers.httpRequest;
// v4.2: no data-source credentials here. The /market_facts route reads its own keys
// (Alpha Vantage, Finnhub, Tiingo, FINRA) from the growth-enrich Railway environment.
// n8n orchestrates; it holds none. Variable names: SETUP_railway.md, Part 1.
const diag = {};
const errStr = e => { try { if(e==null) return 'null'; if(typeof e==='string') return e;
  if(e.message) return String(e.message); if(e.description) return String(e.description);
  if(e.error) return (typeof e.error==='string'?e.error:JSON.stringify(e.error));
