  price_target, analyst_count, rec_trends, short_interest, short_pct_basis, peer_median_pe_basis, fwd_pe_basis, recommendation_mean, recommendation_key, analyst_actions_recent, eps_estimates, fwd_pe:(fwd_pe!=null?Math.round(fwd_pe*100)/100:null),
