try {
  if (_in && (_in.type==='error' || _in.error)) { apiError = (_in.error && (_in.error.message||JSON.stringify(_in.error))) || 'api error'; }
  else if (Array.isArray(_in.content)) { const t=_in.content.find(b=>b && b.type==='text'); text = t ? t.text : ''; }
  else if (_in.choices) { text = _in.choices[0].message.content || ''; }
} catch(e){ apiError = String(e).slice(0,200); }
