  } catch(e){ parse_error = String(e).slice(0,200); }
}
return [{ json: { spec: spec, spec_ok: !!spec, parse_error: parse_error, api_error: apiError, raw: (text||'').slice(0,600) } }];

// === Render Tables: ALL numeric tables in the report are rendered here from RESULT (Run Code).
