  else if (R.result && typeof R.result === 'string') res = JSON.parse(R.result);
  else if (R.output && typeof R.output === 'string') res = JSON.parse(R.output);
} catch(e){ res = { _parse_error: String(e), _raw: (typeof R==='string'?R:JSON.stringify(R)).slice(0,800) }; }

if (res._parse_error || res.error) {
