// --- shape normalizers: LLM (Stage 2a) may emit arrays OR objects-keyed-by-name.
// Deterministic render must not trust the shape. Coerce to array before any iteration.
const asArray = (v)=>{
  if (v===null || v===undefined) return [];
  if (Array.isArray(v)) return v;
  if (typeof v === 'object') {
    // object keyed by block/arg name -> array, injecting the key as a label field
    return Object.keys(v).map(k=>{
      const item = v[k];
      if (item && typeof item === 'object' && !Array.isArray(item)) {
        return Object.assign({ _key:k, name:(item.name||item.block||k), side:(item.side||undefined) }, item);
      }
      return { _key:k, name:k, value:item };
    });
  }
  return []; // scalar/string -> nothing iterable
};
const isObj = (v)=> v && typeof v==='object' && !Array.isArray(v);

const n = (x,d=2)=> (x===null||x===undefined||Number.isNaN(x)) ? '—' : (typeof x==='number'? x.toFixed(d) : String(x));
const pct = (x,d=2)=> (x===null||x===undefined)? '—' : (typeof x==='number'? x.toFixed(d)+'%' : String(x));
const row = (...c)=> '| ' + c.join(' | ') + ' |';
const H = [];

