// the bug was reported, not everywhere the constant lived. When killing a hardcoded constant, grep
// for the CONSTANT, not for the symptom -- and pin every renderer, not the one you happened to read.
const _gpsMax = (res && res.gps && typeof res.gps.max === 'number') ? res.gps.max : null;
H.push(row(el.ticker, n(gps.total,0)+'/'+(_gpsMax==null?'?':n(_gpsMax,0)), pct(gbase.implied_cagr_pct), '$'+n(res.pwfv),
