    const _redact = (t) => String(t)
      .replace(/(apikey|token|client_secret|key)=[A-Za-z0-9_\-]{8,}/gi, '$1=[REDACTED]')
      .replace(/\b[A-Z0-9]{14,}\b/g, '[REDACTED]')
