  } else if (isObj(S)) {
    // actual Stage2a shape: flat dict {"g0.75_pe0.8": impliedCAGR, ...} -> pivot to matrix
    const keys = Object.keys(S);
    const parse = k => { const m = k.match(/g([0-9.]+)_pe([0-9.]+)/); return m? {gm:m[1], pm:m[2]} : null; };
    const parsed = keys.map(k=>({k, p:parse(k)})).filter(x=>x.p);
    if (parsed.length) {
      const gms = [...new Set(parsed.map(x=>x.p.gm))];
