      for (const gm of gms) {
        const cells = pms.map(pm=>{ const hit=parsed.find(x=>x.p.gm===gm&&x.p.pm===pm); return hit? pct(S[hit.k]) : '—'; });
        H.push(row(gm, ...cells));
      }
      H.push('\n_g× = multiplier on base growth; PE× = multiplier on base future P/E_');
