// ---------- 9. EVIDENCE PACK — numeric substrate for the qualitative blocks (E/A_runway/G/H) and radar.
// 2b MUST cite these values when justifying scores and radar thresholds. Without this -> score_unevidenced.
let ev = [];
try {
  const pl = $('Eligibility').first().json || {};
  const num = (v,d=2)=> (v==null||Number.isNaN(v))?'—':(typeof v==='number'?v.toFixed(d):String(v));
  const pctv = (v,d=1)=> (v==null)?'—':(typeof v==='number'?(v*100).toFixed(d)+'%':String(v));
  // margins for E_moat / B
  const gd = (res.gps && res.gps.blocks && res.gps.blocks.pinned_ACDF && res.gps.blocks.pinned_ACDF.detail) || {};
  const om = pl.op_margin_series || (gd.B && gd.B.op_margin_series) || [];
  ev.push('- Op-margin series (by FY): ['+asArray(om).map(x=>typeof x==='number'?(x*100).toFixed(1)+'%':x).join(', ')+']');
  ev.push('- Rev CAGR: 3y='+pctv(pl.rev_cagr_3y)+', 5y='+pctv(pl.rev_cagr_5y)+' | EPS CAGR: 3y='+pctv(pl.eps_cagr_3y)+', 5y='+pctv(pl.eps_cagr_5y));
  ev.push('- ROE='+pctv(pl.roe)+' | FCF-conv='+pctv(pl.fcf_conversion)+' | D/E='+num(pl.debt_to_equity)+' | SBC/rev='+pctv(pl.sbc_to_revenue));
  ev.push('- Dilution CAGR (split-adj)='+pctv(pl.dilution_cagr)+' | levered FCF/share=$'+num(pl.levered_fcf_per_share)+' | levered FCF=$'+num((pl.levered_fcf||0)/1e9)+'B');
  // v2.3: buyback + dividend from SEC primary source
  ev.push('- Buyback executed (latest FY)=$'+num((pl.buyback_latest||0)/1e9)+'B | buyback/FCF='+pctv(pl.buyback_to_fcf)+' | buyback/SBC='+num(pl.buyback_vs_sbc)+'x');
  ev.push('- Dividends paid (latest FY)=$'+num((pl.dividend_paid_latest||0)/1e9)+'B | dividend growth CAGR='+(pl.dividend_growth_cagr==null?'[n/a]':pctv(pl.dividend_growth_cagr)));
  ev.push('- Rel strength: 6m='+pctv(pl.rel_strength_6m)+', 12m='+pctv(pl.rel_strength_12m)+' | ERB 90d='+(pl.erb_90d==null?'[UNVERIFIED]':pctv(pl.erb_90d)));
  ev.push('- Cash=$'+num((pl.cash||0)/1e9)+'B | ST-inv=$'+num((pl.st_investments||0)/1e9)+'B | fwd P/E='+(pl.fwd_pe==null?'[UNVERIFIED]':num(pl.fwd_pe))+' | PEG='+(pl.peg==null?'[UNVERIFIED]':num(pl.peg,2))+' | pe_hist_median='+(pl.pe_hist_median==null?'[UNVERIFIED]':num(pl.pe_hist_median)));
  // v2.3 Wave-2: peer anchor for pe_cap + short interest (yahoo tier)
  if (pl.peer_multiples && pl.peer_multiples.length) {
    const pm = pl.peer_multiples.filter(p=>p && p.fwd_pe!=null).map(p=>p.ticker+' fwd_pe='+num(p.fwd_pe)+(p.eps_growth_pct!=null?' g='+num(p.eps_growth_pct)+'%':'')).join(' | ');
    const perErrs = pl.peer_multiples.filter(p=>p && p.error).map(p=>p.ticker+': '+p.error).join(' | ');
    // v4.2.2: this line hardcoded the word 'fwd' regardless of the real basis, so an in-house
    // TRAILING median (NFLX: 95.09, inflated by WBD's collapsed earnings) travelled through the
    // whole report wearing a forward name. A number's basis travels WITH it.
    const _pmb = pl.peer_median_pe_basis || (pl.peer_median_pe!=null ? 'yahoo_forward' : null);
    const _trailing = !!(_pmb && _pmb.indexOf('trailing')>=0);
    ev.push('- PEER multiples (yahoo tier): '+(pm||'[none]')+' || PEER-median '+(_trailing?'TRAILING':'fwd')
      +' P/E='+(pl.peer_median_pe==null?'[UNVERIFIED]':num(pl.peer_median_pe))
      +' (basis: '+(_pmb||'unknown')+'; NOT sector median — median of peers)');
    if (_trailing) ev.push('- Peer median is TRAILING, not forward: do NOT compare it against a forward P/E. '
      +'It is EXCLUDED from the PE cap -- a peer set with depressed earnings inflates a trailing median '
