    if (perErrs) ev.push('- ⚠️ Peer fetch errors: '+perErrs.slice(0,200));
  } else {
    ev.push('- ⚠️ PEER multiples: array is empty/missing entirely (not just null values) — enrich_yf returned peer_multiples=[] or payload.peer_multiples was not passed through from Growth Enrich.');
  }
  // v4.2.4: this line said 'of float' while the FINRA block above says, of the SAME company on the
  // SAME run, '% of shares OUTSTANDING, not float'. Two bases, one report -- and THIS is the section
  // the memo, auditor and arbiter are instructed to cite VERBATIM, so the mislabel travels onward as
  // fact. The identical disease was fixed for peer_median_pe a few lines up ("a number's basis
  // travels WITH it") and this line was left standing in that same edit.
  // UNITS DIFFER AND THEY BITE: short_pct_float is a FRACTION (pctv scales it by 100);
  // short_pct_shares_outstanding is already PERCENT (the FINRA block prints it via n(), unscaled).
