  const _siEv = (el && el.short_interest) || null;
  const _soPct = (_siEv && typeof _siEv==='object' && typeof _siEv.short_pct_shares_outstanding==='number') ? _siEv.short_pct_shares_outstanding : null;
  const _flPct = (typeof pl.short_pct_float==='number') ? pl.short_pct_float*100 : null;
  const _siEvParts = [];
  // v4.2.7: carry the EXACT share count and days-to-cover, not just the percentage. The Stage 4
