  // DATE, and Stage 2b is told to cite settlement date + days-to-cover. Yet the exact count lived
  // ONLY in the raw GROUND_TRUTH JSON: section 1 rounds it to '104.12M' and this line, the one the
  // memo is told to cite VERBATIM, carried neither the count nor days-to-cover. NFLX 2026-07-17
  // proved it: MAJOR short_interest_unsourced, run blocked at the gate, full LLM spend burned.
  // A citation source that cannot satisfy the gate reading it is a trap, not a source.
  if (_soPct!=null) _siEvParts.push(num(_soPct)+'% of shares OUTSTANDING'
    + (_siEv.short_shares!=null ? ' = ' + Number(_siEv.short_shares).toLocaleString('en-US') + ' shares' : '')
    + ' (FINRA primary'+(_siEv.settlement_date?', settled '+_siEv.settlement_date:'')+')'
    + (_siEv.days_to_cover!=null ? ', days-to-cover '+num(_siEv.days_to_cover) : ''));
  if (_flPct!=null) _siEvParts.push(num(_flPct)+'% of FLOAT (yfinance)');
  ev.push('- Short interest: '+(_siEvParts.length?_siEvParts.join(' | '):'[UNVERIFIED]')+' | fwd_pe/peer-median='+(pl.fwd_pe_vs_peer==null?'—':num(pl.fwd_pe_vs_peer,2)+'x'));
  if (_soPct!=null && _flPct!=null && Math.abs(_soPct-_flPct)<0.05) ev.push('- ⚠️ The float-basis and outstanding-basis short-interest figures are within 0.05pp of each other. Float is a SUBSET of shares outstanding, so a genuine float figure must read HIGHER. Near-equality means the "float" number is not actually float-based -- cite the FINRA outstanding figure and its basis, not the yfinance label.');
  // v3.2: surface WHY yfinance fields are [UNVERIFIED], on every run (pass or fail), not
  // only in Send Rework's DIAG. Previously growth_diag.yf_errors was silently dropped on
  // any successful run -- 5 consecutive META passes gave zero visibility into the cause.
  try {
    const gd = pl.growth_diag || {};
    if (pl.fwd_pe==null || pl.peer_median_pe==null) {
      if (gd.yf_errors && Object.keys(gd.yf_errors).length) {
        ev.push('- ⚠️ yfinance diag: '+JSON.stringify(gd.yf_errors).slice(0,200));
      } else if (gd.yf_enrich) {
        ev.push('- ⚠️ yfinance diag: enrich call failed: '+String(gd.yf_enrich).slice(0,200));
      } else {
        ev.push('- ⚠️ yfinance diag: fwd_pe/peer_median null, but growth_diag contains no explicit error '
          + '(the microservice returned empty fields WITHOUT an exception — likely info_empty on Yahoo\'s side).');
      }
    }
  } catch(e) {}
  if (pl.rpo!=null) ev.push('- RPO=$'+num(pl.rpo/1e9)+'B (for the tripwire — set a NUMERIC threshold, e.g. <$'+num(pl.rpo*0.9/1e9)+'B)');
  if (pl.split_events && pl.split_events.length) ev.push('- Split-adjusted: '+pl.split_events.map(e=>e.factor+':1@'+(e.period||'')).join(', '));
} catch(e){ ev.push('[EVIDENCE payload unavailable: '+String(e).slice(0,80)+']'); }
if (ev.length) {
  H.push('\n### EVIDENCE PACK (numbers for qualitative scores and radar thresholds — cite VERBATIM)');
  H.push(ev.join('\n'));
  H.push('\n_Rule: every qualitative score (E_moat, A_runway, G, H) and every Forward Radar row '
    + 'must contain a concrete number from here. A label with no magnitude ("very low", "near zero") = score_unevidenced / radar_no_threshold._');
}

// v4.2.2: a defect the reader never sees is a defect that reaches the verdict. NFLX carried a
// corrupted EPS series, a 3.5-year-stale short-interest settlement and a mislabelled peer basis
// through an entire run; only Stage 2b -- an LLM, reading growth_diag -- mentioned any of them.
// This layer is trusted, so when it breaks it must SAY SO, first and loudest.
const _defects = [];
try {
  const _pl = $('Eligibility').first().json || {};
  if (_pl.eps_series_unreliable) _defects.push('**EPS series UNRELIABLE** — '
    + (_pl.eps_series_unreliable_reason || 'unconfirmed split')
    + '. EPS CAGR is withheld and the growth block is scored out of a reduced max. '
    + 'eps0, IV, PWFV, MoS and implied_cagr are UNAFFECTED (single-year figures do not span the break).');
  const _si = _pl.short_interest;
  if (_si && _si._basis_error) _defects.push('**Short-interest basis error** — ' + _si._basis_error);
  const _gd = _pl.growth_diag || {};
  if (_gd.market_facts_errors && _gd.market_facts_errors.finra_short)
    _defects.push('**Short interest withheld** — ' + _gd.market_facts_errors.finra_short);
  const _ef = (_pl._edgar && _pl._edgar.flags) || {};
  if (_ef.confirmed_splits_none && _pl.eps_series_unreliable)
    _defects.push('**EDGAR split confirmation absent** — ' + _ef.confirmed_splits_none);
} catch(e){}
if (_defects.length) H.unshift('### DATA DEFECTS (deterministic layer) — read these before the numbers\n'
  + _defects.map(d=>'- '+d).join('\n') + '\n');
return [{ json: { tables_md: H.join('\n'), render_ok:true, result_json: res } }];

const _in = $input.first().json;

function _parseResponse(json){
  if (!json) return { text:'', blockTypes:[], apiError:'empty response object', stopReason:'' };
  if (json.type === 'error' || json.error) {
    const em = (json.error && (json.error.message || JSON.stringify(json.error))) || JSON.stringify(json).slice(0,500);
    return { text:'', blockTypes:[], apiError: em, stopReason:'' };
  }
  let text=''; const blockTypes=[];
  if (Array.isArray(json.content)) {
    for (const block of json.content) {
      if (!block) continue;
      blockTypes.push(block.type || 'unknown');
      if (block.type === 'text' && typeof block.text === 'string') text += block.text;
    }
  }
  return { text, blockTypes, apiError:null, stopReason: json.stop_reason || '' };
}

const { text, blockTypes, apiError, stopReason } = _parseResponse(_in);

let memo_text, memo_ok = true;
if (apiError) {
  memo_text = '\u26a0\ufe0f RUNNER_ERROR: Stage2b API call returned an error response: ' + apiError;
  memo_ok = false;
} else if (stopReason === 'max_tokens') {
  memo_text = '\u26a0\ufe0f RUNNER_ERROR: Stage2b memo generation TRUNCATED at max_tokens \u2014 memo incomplete; raise the limit or shorten stage2b instructions.';
  memo_ok = false;
} else if (!text || !text.trim()) {
  memo_text = '\u26a0\ufe0f RUNNER_ERROR: Stage2b returned no text content block. Block types received: [' + blockTypes.join(', ') + ']. stop_reason=' + (stopReason || '(none)') + '.';
  memo_ok = false;
} else {
  memo_text = text;
}
return [{ json: { memo_text, memo_ok, block_types: blockTypes } }];

// v3.9 NUMBER AUDIT — deterministic anti-hallucination layer.
// Extracts every material number from the memo prose and matches it against a whitelist built
// from RESULT + GROUND_TRUTH + rendered tables. Python FINDS unsourced numbers; the auditor
// (LLM) then JUDGES severity — instead of one LLM hunting another LLM's inventions by eye.
const memoJ = $('Extract Memo').first().json;
const memo = memoJ.memo_text || '';
const srcBlob = JSON.stringify($('Run Code').first().json) + ' ' +
                JSON.stringify($('Eligibility').first().json) + ' ' +
                (($('Render Tables').first().json||{}).tables_md||'');
// whitelist: every numeric token in the sources, plus scale/format variants the memo may use
const wl = new Set();
function addVariants(x){
  if (!isFinite(x)) return;
  [x, x/1e6, x/1e9, x*100, x/100, x/1e3].forEach(v=>{
    [0,1,2,3].forEach(dp=>wl.add(Number(Math.abs(v)).toFixed(dp)));
  });
}
(srcBlob.match(/-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/g)||[]).forEach(t=>addVariants(parseFloat(t)));
// candidate numbers in the memo: skip years, small ordinals, radar IDs
const out=[]; let total=0;
const sentences = memo.split(/(?<=[.!?])\s+|\n/);
for (const sent of sentences){
  if (sent.includes('[UNVERIFIED]')) continue;              // honestly marked, not a claim
  // negative lookbehind: skip numbers glued to letters (FY26, Q3, BR2) — they are labels;
  // capture the $ / % marker so scale intent survives
  const nums = [];
  const re = /(?<![A-Za-z\d])(\$?\d[\d,]*(?:\.\d+)?%?)/g;
  let mm; while ((mm=re.exec(sent))!==null) nums.push(mm[1]);
  for (const raw of nums){
    const clean = raw.replace(/[$,%]/g,'').replace(/,/g,'');
    const v = parseFloat(clean);
    if (!isFinite(v)) continue;
    if (/^(19|20)\d{2}$/.test(clean)) continue;              // years
    if (!raw.includes('$') && !raw.includes('%') && v<=12 && Number.isInteger(v)) continue; // ordinals/counts
    // bare section-style numbers (6.1, 2.3) without $/% and small: labels, not claims
    if (!raw.includes('$') && !raw.includes('%') && v<=12) continue;
    total++;
    let matched=false;
    for (const dp of [0,1,2,3]){
      if (wl.has(Math.abs(v).toFixed(dp))) { matched=true; break; }
    }
    if (!matched) out.push({value: raw, context: sent.trim().slice(0,140)});
  }
}
return [{ json: { memo_numbers_total: total, unmatched_count: out.length,
  unmatched: out.slice(0,25),
  _note: 'unmatched = number in memo prose with NO counterpart in RESULT/GROUND_TRUTH/tables (within rounding & B/M/% scaling). Auditor must trace each: truly unsourced -> MAJOR unsourced_number.' } }];

// v4.2.5 — Collect Usage. Every LLM node here is an httpRequest, so the provider's own `usage`
// block already comes back in the response and, until now, was silently discarded on every run.
// This node only HARVESTS. It computes nothing: prices and arithmetic live in pricing.py, one
// canonical home, covered by the python suite. A price edit must not cost a workflow re-import.
//
// $('Node') THROWS when the node did not execute (e.g. the Core-V branch). That throw is
// information, not an error: "did not run" is a real zero. It must never be confused with
// "ran but we could not read the meter", which is money spent and unmeasured. Two different
// unknowns; pricing.py keeps them apart and so must this.
const STAGES = [
  ['Stage 1 Perplexity',  'perplexity', 'sonar-pro'],
  ['Stage 2a Claude',     'anthropic',  'claude-sonnet-5'],
  ['Stage 2b Lite',       'anthropic',  'claude-sonnet-5'],
];

const stages = [];
for (const [name, provider, model] of STAGES) {
  let ran = true, response = null;
  try {
    const item = $(name).first();
    response = (item && item.json) ? item.json : null;
    if (response == null) ran = false;
  } catch (e) {
    ran = false;   // node absent from this execution path
  }
  stages.push({ stage: name, provider, model, response, ran });
}

// The model ids above are duplicated from each node's request body — n8n gives a Code node no way
// to read a sibling's parameters. That duplication is a KNOWN defect: change a model in a node
// body and this list goes stale silently, mispricing the run against the old model's rate. The
// guard: if a provider echoes the model it actually served, compare and flag the drift rather
// than trust the constant. Anthropic and OpenAI both echo `model`; Gemini/xAI/Perplexity vary.
const drift = [];
for (const s of stages) {
  const echoed = s.response && (s.response.model || s.response.modelVersion);
  if (echoed && typeof echoed === 'string' && s.model && echoed.indexOf(s.model) !== 0
      && s.model.indexOf(echoed) !== 0) {
    drift.push(s.stage + ': node body says ' + s.model + ', provider served ' + echoed);
    s.model_drift = echoed;
  }
}

return [{ json: { stages, ticker: ($('Eligibility').first().json || {}).ticker || null,
                  model_drift: drift, collected_at: new Date().toISOString() } }];

// ---- Assemble Lite v1.0 — the Lite report: deterministic core + one memo, no judicial chain.
// The gate/audit/arbiter are ABSENT by design (operator decision 2026-07-18: Lite is the
// default instrument; the full consilium runs on demand for finalists). Their replacement is
// deterministic and printed at the TOP: the NUMBER_AUDIT banner — every memo number with no
// counterpart in RESULT/GROUND_TRUTH/tables, listed before anything else is read.
const el = $('Eligibility').first().json;
const ticker=el.ticker, chat_id=el.chat_id, company_title=el.company_title||'';
function safe(node,pick){ try { return pick($(node).first().json)||'[no data]'; } catch(e){ return '[no data]'; } }
const memo   = safe('Extract Memo', j=>j.memo_text);
const tables = safe('Render Tables', j=>j.tables_md);
const fact   = safe('Stage 1 Perplexity', j=>j.choices[0].message.content);
const edgar  = safe('Eligibility', j=>j._edgar?JSON.stringify(j._edgar,null,2):'[no EDGAR metadata surfaced]');
let final_verdict='UNPARSED';
try { final_verdict = $('Render Tables').first().json.result_json.verdict_cap || 'UNPARSED'; } catch(e){}
const date=new Date().toISOString().slice(0,10);

// NUMBER_AUDIT banner — the Lite substitute for the adversarial chain. Deterministic, free.
let naBanner='';
try {
  const na = $('Number Audit').first().json;
  if (na && na.unmatched_count > 0) {
    naBanner = '## \u26a0\ufe0f NUMBER AUDIT (deterministic) — read BEFORE the memo\n'
      + 'Lite runs WITHOUT the adversarial audit chain. This deterministic screen matched every '
      + 'memo number against RESULT / GROUND_TRUTH / tables (rounding and B/M/% scaling accounted for). '
      + na.unmatched_count + ' of ' + na.memo_numbers_total + ' numbers have NO counterpart — treat each as '
      + 'UNSOURCED until you check it yourself, or escalate the ticker to a full consilium run:\n'
      + na.unmatched.map(u=>'- `'+u.value+'` — "...'+String(u.context).replace(/`/g,"'")+'..."').join('\n')
      + '\n';
  } else if (na) {
    naBanner = '## NUMBER AUDIT (deterministic)\nAll ' + na.memo_numbers_total
      + ' memo numbers matched RESULT/GROUND_TRUTH/tables. No unsourced numbers detected.\n';
  }
} catch(e){ naBanner = '## \u26a0\ufe0f NUMBER AUDIT\n[audit node did not run — treat every memo number as unverified]\n'; }

// ---------- v4.2.5 run cost ----------
// Tokens are facts (each provider's own usage block). Dollars are an ESTIMATE and say so, every
// time, in the same breath as the number. A billing section must never take the report down:
// Cost Ledger runs onError=continueRegularOutput, so this handles its absence as a first-class
// case rather than assuming success.
let costLedger = null;
try { costLedger = $('Cost Ledger').first().json || null; } catch(e) { costLedger = null; }
let costSection, costSummary;
if (!costLedger || costLedger._FALLBACK || !costLedger.rows) {
  costSection = '_Cost ledger unavailable this run (the /cost call failed or did not execute). '
    + 'This is NOT a $0 run — the tokens were spent and the meter was lost._';
  costSummary = 'cost: [UNVERIFIED — ledger unavailable]';
} else {
  const t = costLedger.totals || {}, pt = costLedger.price_table || {};
  const L = [];
  L.push('| Stage | Model | In | Out | Cached rd/wr | Est. USD |');
  L.push('|---|---|---|---|---|---|');
  const fmt = v => (v==null?'—':Number(v).toLocaleString('en-US'));
  for (const r of costLedger.rows) {
    let cost;
    if (r.status === 'not_run')       cost = '_not run_';
    else if (r.status === 'meter_lost') cost = '**meter lost**';
    else if (r.est_cost_usd == null)  cost = '**[UNVERIFIED]**';
    else                              cost = '$' + Number(r.est_cost_usd).toFixed(4);
    L.push('| ' + r.stage + ' | ' + (r.model||'—') + ' | ' + fmt(r.input_tokens) + ' | '
      + fmt(r.output_tokens) + ' | ' + fmt(r.cache_read_tokens) + '/' + fmt(r.cache_write_tokens)
      + ' | ' + cost + ' |');
  }
  L.push('| **TOTAL** |  | **' + fmt(t.input_tokens) + '** | **' + fmt(t.output_tokens)
    + '** |  | **$' + Number(t.est_cost_usd||0).toFixed(4) + (t.est_cost_is_partial?' (PARTIAL)':'') + '** |');
  L.push('');
  L.push('_' + (costLedger._basis||'') + '_');
  if (t.est_cost_is_partial) {
    L.push('');
    L.push('**This total is PARTIAL — the real bill is HIGHER.**');
    if ((t.excluded_unpriced||[]).length)   L.push('- No price in the table, excluded: ' + t.excluded_unpriced.join(', '));
    if ((t.excluded_meter_lost||[]).length) L.push('- Ran but usage unreadable, excluded: ' + t.excluded_meter_lost.join(', '));
    if ((t.understated_incomplete||[]).length) L.push('- Token-only (provider also bills per request): ' + t.understated_incomplete.join(', '));
  }
  const warn = [];
  if (pt.stale) warn.push('price table is ' + pt.age_days + ' days old (>' + pt.stale_after_days + ') — REFRESH IT');
  for (const e of (pt.expiring||[])) warn.push(e.model + ': ' + e.status + ' ' + e.on + ' — ' + e.detail);
  if ((pt.unverified_by_operator||[]).length) warn.push('rates never checked against vendor pages by the operator: ' + pt.unverified_by_operator.join(', '));
  let drift = [];
  try { drift = $('Collect Usage').first().json.model_drift || []; } catch(e) {}
  for (const d of drift) warn.push('MODEL DRIFT — ' + d + ' (priced against the wrong model)');
  if (warn.length) { L.push(''); L.push('**Price-table warnings:**'); for (const w of warn) L.push('- ⚠️ ' + w); }
  L.push('');
  L.push('_Price table as of ' + (pt.as_of||'?') + ' (' + (pt.age_days!=null?pt.age_days:'?') + 'd old)._');
  costSection = L.join('\n');
  costSummary = '$' + Number(t.est_cost_usd||0).toFixed(2) + (t.est_cost_is_partial?'+ (partial)':'')
    + ' · ' + fmt(t.input_tokens) + ' in / ' + fmt(t.output_tokens) + ' out';
}


const GLOSSARY = [
'## 9. Glossary — every term used above, in plain words',
'',
'**IV (Intrinsic Value).** Our estimate of what one share is worth today. Computed by projecting earnings per share ten years ahead, applying a terminal P/E, and discounting back at the hurdle rate. All in Python, never by the language model.',
'**IVC.** The intrinsic-value calculator itself — the fixed formula that turns growth, P/E and hurdle assumptions into IV.',
'**FV10.** Projected value of one share ten years from now, before discounting back to today.',
'**eps_terminal.** Earnings per share the model expects in year ten, after the fade.',
'**Fade.** Growth is not held constant: in years six to ten the growth rate glides down toward the terminal rate, because no company compounds at its peak rate forever.',
'**PWFV (Probability-Weighted Fair Value).** The bear, base and bull IVs blended by their scenario weights. This is the single fair-value number the verdict leans on.',
'**MoS (Margin of Safety).** How far the current price sits below IV, as a percent of price. Negative MoS means the stock trades ABOVE our estimate of its worth.',
'**MoS ladder.** The three entry prices at which you would own the stock with a 10, 20 or 30 percent discount to IV. The arbiter names which rung this idea must reach before any buy.',
'**Hurdle / hurdle_gate.** The minimum acceptable return: 12 percent per year. The gate FAILS when the implied ten-year return at today\'s price is below 12 percent — meaning the price already assumes more growth than the base case delivers.',
'**Implied CAGR.** The annual return you would earn over ten years buying at today\'s price if our base scenario plays out exactly. Compare it to the 12 percent hurdle.',
'**verdict_cap.** A hard ceiling on the verdict, set deterministically: implied CAGR below 12 percent caps the name at AVOID; between 12 and 16 percent caps it at WATCH+. No prose can override it.',
'**GPS.** The Growth Pipeline Scorecard, up to 100 points across blocks: A growth, B profitability, C valuation, D balance sheet, E moat, F forecast trend, G capital allocation, H sentiment. It describes QUALITY; it does not set the verdict — the gates do.',
'**GPS denominator (e.g. 62/95).** When an input for a block is unavailable, that block\'s maximum points are removed from the scale instead of scoring a silent zero. A score out of 95 means 5 points of scale were unmeasurable this run. Do not compare raw GPS across tickers without checking the denominator.',
'**Dual basis (GAAP vs FCF).** The same company valued twice: on GAAP earnings and on free cash flow per share. Stock-based compensation makes these diverge; the verdict always follows the more conservative leg.',
'**PEG.** Forward P/E divided by expected EPS growth in percent. Around 1 is conventionally fair; well above 2 means you pay heavily for each point of growth.',
'**Forward P/E.** Today\'s price divided by next year\'s CONSENSUS earnings estimate. Trailing P/E uses last year\'s reported earnings — the two are different bases and are never mixed here.',
'**ERB.** Earnings-revision breadth: whether analysts have been raising or cutting estimates over the last 90 days. Positive means estimates are rising.',
'**Days-to-cover.** Short interest divided by average daily volume: how many trading days shorts would need to buy back their entire position.',
'**Net skew.** The probability-weighted sum of all bull arguments minus all bear arguments, in dollars of IV impact. Negative skew with a BUY verdict demands an explanation.',
'**DI (Disagreement Index).** How much the adversarial audit and the arbiter disagreed with the memo. 0-2 consensus; 3-5 divergence; 6 or more CONTESTED — trades are blocked until the listed items are verified by hand.',
'**[UNVERIFIED].** The datum could not be confirmed from an acceptable source this run. It is a stated gap, never a zero.',
'**[AGGREGATOR].** The figure comes from a sell-side tracker (Benzinga, TipRanks and similar), not from primary filings or tier-1 press. Usable, lower confidence.',
'**EVIDENCE PACK.** The block of exact figures the memo is required to cite verbatim when justifying qualitative scores and radar thresholds.',
'**DATA DEFECTS banner.** When the deterministic layer detects its own data problem (a stale field, a basis error, an unconfirmed split), it prints the defect at the top of section 1 so the flaw travels with the report instead of hiding under it.',
].join('\n');

const md=[ '# '+ticker+(company_title?' — '+company_title:'')+' — GROWTH LITE Report ('+date+')',
 '> Mandate: 12–16% CAGR / 10y, hurdle 12% (floor). Verdict (deterministic verdict_cap): **'+final_verdict+'**',
 '> LITE MODE: no gate, no adversarial audit, no arbiter, no DI. The deterministic NUMBER AUDIT below is the only screen. For finalists and contested names, run the full consilium.', '',
 naBanner,
 '## 1. Numeric layer (deterministic, Python)', tables, '',
 '## 2. Memo (judgment over the numbers above)', memo, '',
 '## 3. Fact Pack (Perplexity, compact)', fact, '',
 '## 4. EDGAR provenance', '```json', edgar, '```', '',
 '## 5. Run cost (tokens exact, dollars estimated)', costSection, '',
 GLOSSARY ].join('\n');
const fname=ticker+'_'+date.replace(/-/g,'')+'_lite.md';
return [{ json:{ chat_id, ticker, di:null, di_class:'LITE', final_verdict, contested:false,
  cost_summary: costSummary, cost_ledger: costLedger },
  binary:{ data:{ data:Buffer.from(md,'utf8').toString('base64'), mimeType:'text/markdown', fileName:fname } } }];
